describe('Search Filter - Exclude Term', () => {
    beforeEach(() => {
        cy.visit('/search'); // Replace with the actual search page URL
    });

    it('should exclude the term when prefixed with "-"', () => {
        cy.get('input[name="search"]').type('apple -banana');
        cy.get('button[type="submit"]').click();
        cy.get('.search-results').should('not.contain', 'banana');
        cy.get('.search-results').should('contain', 'apple');
    });

    it('should return no results when all terms are excluded', () => {
        cy.get('input[name="search"]').type('-apple -banana');
        cy.get('button[type="submit"]').click();
        cy.get('.search-results').should('not.exist');
    });
});
